package com.cryptotrading.exchange.domain;

import java.util.Objects;
import java.util.regex.Pattern;

/**
 * Idempotency key of an order, generated by the platform <em>before</em> submission and persisted first.
 * Re-submitting the same id is rejected by the exchange as a duplicate, and the id allows querying the
 * order when the submission result is unknown (timeout, 5xx).
 */
public record ClientOrderId(String value) {

    /** Format accepted by Binance Spot ({@code newClientOrderId}). */
    private static final Pattern FORMAT = Pattern.compile("^[a-zA-Z0-9_-]{1,36}$");

    public ClientOrderId {
        Objects.requireNonNull(value, "value");
        if (!FORMAT.matcher(value).matches()) {
            throw new IllegalArgumentException("Invalid client order id: " + value);
        }
    }

    @Override
    public String toString() {
        return value;
    }
}
